const { World, Before, After, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

const templateHtml = fs.readFileSync(
  path.resolve(__dirname, '../../../assets/app-template.index.html'),
  'utf-8'
);

class AppWorld extends World {
  constructor(params) {
    super(params);
    this.window = null;
    this.document = null;
  }

  openApp() {
    this.window = new Window({
      url: 'http://localhost/',
      pretendToBeVisual: true,
    });
    this.document = this.window.document;
    this.document.documentElement.innerHTML = templateHtml
      .replace(/<!doctype html>/i, '')
      .replace(/<html[^>]*>/i, '')
      .replace(/<\/html>/i, '');
    // Set body content from template
    const bodyMatch = templateHtml.match(/<body[^>]*>([\s\S]*)<\/body>/i);
    if (bodyMatch) {
      this.document.body.innerHTML = bodyMatch[1];
    }
  }

  typeIntoInput(input, text) {
    input.value = text;
    input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  }

  pressEnter(input) {
    const event = new this.window.KeyboardEvent('keydown', {
      key: 'Enter',
      code: 'Enter',
      keyCode: 13,
      which: 13,
      bubbles: true,
    });
    input.dispatchEvent(event);
  }

  pressEscape(input) {
    const event = new this.window.KeyboardEvent('keydown', {
      key: 'Escape',
      code: 'Escape',
      keyCode: 27,
      which: 27,
      bubbles: true,
    });
    input.dispatchEvent(event);
  }

  triggerBlur(input) {
    input.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
  }

  clickElement(el) {
    el.dispatchEvent(new this.window.Event('click', { bubbles: true }));
  }

  doubleClickElement(el) {
    el.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
  }

  hoverElement(el) {
    el.dispatchEvent(new this.window.MouseEvent('mouseenter', { bubbles: true }));
  }

  findTodoByTitle(title) {
    const labels = this.document.querySelectorAll('.todo-list li .view label');
    for (const label of labels) {
      if (label.textContent === title) {
        return label.closest('li');
      }
    }
    return null;
  }

  findAllTodos() {
    return Array.from(this.document.querySelectorAll('.todo-list li'));
  }

  getEditInput(todoEl) {
    return todoEl ? todoEl.querySelector('.edit') : null;
  }

  navigateTo(filter) {
    const routes = { All: '#/', Active: '#/active', Completed: '#/completed' };
    this.window.location.hash = routes[filter] || '#/';
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  reloadApp() {
    const todos = this.getTodosFromStorage();
    const hash = this.window.location.hash;
    this.openApp();
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('load'));
    // Restore localStorage
    if (todos) {
      this.window.localStorage.setItem('todos-shakedown', JSON.stringify(todos));
    }
  }

  getTodosFromStorage() {
    const data = this.window.localStorage.getItem('todos-shakedown');
    return data ? JSON.parse(data) : null;
  }

  completeTodo(title) {
    const todo = this.findTodoByTitle(title);
    if (todo) {
      const checkbox = todo.querySelector('.toggle');
      if (checkbox && !checkbox.checked) {
        this.clickElement(checkbox);
      }
    }
  }
}

setWorldConstructor(AppWorld);

Before(function () {
  this.openApp();
});

After(function () {
  if (this.window) {
    this.window.close();
  }
});

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

// ==================== Given steps ====================

Given('the app is open with no todos', function () {
  // Already opened in Before hook; just verify clean state
  const todos = this.findAllTodos();
  assert.strictEqual(todos.length, 0, 'Expected no todos');
});

Given('the user has added a todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  this.typeIntoInput(input, title);
  this.pressEnter(input);
});

Given('the user has added todos {string} and {string}', function (t1, t2) {
  const input = this.document.querySelector('.new-todo');
  for (const title of [t1, t2]) {
    this.typeIntoInput(input, title);
    this.pressEnter(input);
  }
});

Given('the user has added todos {string}, {string}, and {string}', function (t1, t2, t3) {
  const input = this.document.querySelector('.new-todo');
  for (const title of [t1, t2, t3]) {
    this.typeIntoInput(input, title);
    this.pressEnter(input);
  }
});

Given('the todo {string} is completed', function (title) {
  this.completeTodo(title);
});

Given('all todos are completed', function () {
  const todos = this.findAllTodos();
  for (const todo of todos) {
    const checkbox = todo.querySelector('.toggle');
    if (checkbox && !checkbox.checked) {
      this.clickElement(checkbox);
    }
  }
});

Given('the user navigates to the {string} filter', function (filter) {
  this.navigateTo(filter);
});

// ==================== When steps ====================

When('the user types {string} into the new-todo input and presses Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  this.typeIntoInput(input, text);
  this.pressEnter(input);
});

When('the user presses Enter on the new-todo input', function () {
  const input = this.document.querySelector('.new-todo');
  this.pressEnter(input);
});

When('the user clicks the toggle checkbox on the todo {string}', function (title) {
  const todo = this.findTodoByTitle(title);
  assert.ok(todo, `Todo "${title}" not found`);
  const checkbox = todo.querySelector('.toggle');
  assert.ok(checkbox, 'Toggle checkbox not found');
  this.clickElement(checkbox);
});

When('the user hovers over the todo {string} and clicks the destroy button', function (title) {
  const todo = this.findTodoByTitle(title);
  assert.ok(todo, `Todo "${title}" not found`);
  this.hoverElement(todo);
  const destroyBtn = todo.querySelector('.destroy');
  assert.ok(destroyBtn, 'Destroy button not found');
  this.clickElement(destroyBtn);
});

When('the user double-clicks the label of the todo {string}', function (title) {
  const todo = this.findTodoByTitle(title);
  assert.ok(todo, `Todo "${title}" not found`);
  const label = todo.querySelector('.view label');
  assert.ok(label, 'Label not found');
  this.doubleClickElement(label);
});

When('the user types {string} into the edit input and presses Enter', function (text) {
  const editingLi = this.document.querySelector('.todo-list li.editing');
  assert.ok(editingLi, 'No todo in editing mode');
  const editInput = editingLi.querySelector('.edit');
  assert.ok(editInput, 'Edit input not found');
  this.typeIntoInput(editInput, text);
  this.pressEnter(editInput);
});

When('the user types {string} into the edit input and triggers blur', function (text) {
  const editingLi = this.document.querySelector('.todo-list li.editing');
  assert.ok(editingLi, 'No todo in editing mode');
  const editInput = editingLi.querySelector('.edit');
  assert.ok(editInput, 'Edit input not found');
  this.typeIntoInput(editInput, text);
  this.triggerBlur(editInput);
});

When('the user types {string} into the edit input and presses Escape', function (text) {
  const editingLi = this.document.querySelector('.todo-list li.editing');
  assert.ok(editingLi, 'No todo in editing mode');
  const editInput = editingLi.querySelector('.edit');
  assert.ok(editInput, 'Edit input not found');
  this.typeIntoInput(editInput, text);
  this.pressEscape(editInput);
});

When('the user clears the edit input and presses Enter', function () {
  const editingLi = this.document.querySelector('.todo-list li.editing');
  assert.ok(editingLi, 'No todo in editing mode');
  const editInput = editingLi.querySelector('.edit');
  assert.ok(editInput, 'Edit input not found');
  this.typeIntoInput(editInput, '');
  this.pressEnter(editInput);
});

When('the user clicks the toggle-all checkbox to check it', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  assert.ok(toggleAll, 'Toggle-all checkbox not found');
  if (!toggleAll.checked) {
    this.clickElement(toggleAll);
  }
});

When('the user clicks the toggle-all checkbox to uncheck it', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  assert.ok(toggleAll, 'Toggle-all checkbox not found');
  if (toggleAll.checked) {
    this.clickElement(toggleAll);
  }
});

When('the user completes the todo {string}', function (title) {
  this.completeTodo(title);
});

When('the user clicks the {string} button', function (buttonText) {
  const buttons = this.document.querySelectorAll('button');
  for (const btn of buttons) {
    if (btn.textContent.trim() === buttonText) {
      this.clickElement(btn);
      return;
    }
  }
  assert.fail(`Button "${buttonText}" not found`);
});

When('the user navigates to the {string} filter', function (filter) {
  this.navigateTo(filter);
});

When('the page is reloaded', function () {
  this.reloadApp();
});

// ==================== Then steps ====================

Then('the main section is not visible', function () {
  const main = this.document.querySelector('.main');
  assert.ok(main, '.main section not found');
  const style = this.window.getComputedStyle(main);
  assert.strictEqual(style.display, 'none', 'Main section should be hidden');
});

Then('the footer section is not visible', function () {
  const footer = this.document.querySelector('.footer');
  assert.ok(footer, '.footer section not found');
  const style = this.window.getComputedStyle(footer);
  assert.strictEqual(style.display, 'none', 'Footer section should be hidden');
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  assert.ok(main, '.main section not found');
  const style = this.window.getComputedStyle(main);
  assert.notStrictEqual(style.display, 'none', 'Main section should be visible');
});

Then('the footer section is visible', function () {
  const footer = this.document.querySelector('.footer');
  assert.ok(footer, '.footer section not found');
  const style = this.window.getComputedStyle(footer);
  assert.notStrictEqual(style.display, 'none', 'Footer section should be visible');
});

Then('a todo item with title {string} and completed {boolean} is in the list', function (title, completed) {
  const todo = this.findTodoByTitle(title);
  assert.ok(todo, `Todo "${title}" not found in the list`);
  const checkbox = todo.querySelector('.toggle');
  assert.ok(checkbox, 'Toggle checkbox not found');
  assert.strictEqual(checkbox.checked, completed, `Expected completed=${completed} for "${title}"`);
});

Then('the todo list is empty', function () {
  const todos = this.findAllTodos();
  assert.strictEqual(todos.length, 0, `Expected empty todo list, found ${todos.length}`);
});

Then('the new-todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'New-todo input not found');
  assert.strictEqual(input.value, '', 'New-todo input should be empty');
});

Then('the todo {string} has completed {boolean}', function (title, completed) {
  const todo = this.findTodoByTitle(title);
  assert.ok(todo, `Todo "${title}" not found`);
  const checkbox = todo.querySelector('.toggle');
  assert.ok(checkbox, 'Toggle checkbox not found');
  assert.strictEqual(checkbox.checked, completed, `Expected completed=${completed}`);
});

Then('the todo {string} has the CSS class {string}', function (title, className) {
  const todo = this.findTodoByTitle(title);
  assert.ok(todo, `Todo "${title}" not found`);
  assert.ok(todo.classList.contains(className), `Todo should have class "${className}"`);
});

Then('the todo {string} is not in the list', function (title) {
  const todo = this.findTodoByTitle(title);
  assert.strictEqual(todo, null, `Todo "${title}" should not be in the list`);
});

Then('the todo {string} is visible in the list', function (title) {
  const todo = this.findTodoByTitle(title);
  assert.ok(todo, `Todo "${title}" should be in the list`);
  const style = this.window.getComputedStyle(todo);
  assert.notStrictEqual(style.display, 'none', `Todo "${title}" should be visible`);
});

Then('the edit input for the todo contains {string}', function (text) {
  const editingLi = this.document.querySelector('.todo-list li.editing');
  assert.ok(editingLi, 'No todo in editing mode');
  const editInput = editingLi.querySelector('.edit');
  assert.ok(editInput, 'Edit input not found');
  assert.strictEqual(editInput.value, text, `Edit input should contain "${text}"`);
});

Then('the edit input is focused', function () {
  const editingLi = this.document.querySelector('.todo-list li.editing');
  assert.ok(editingLi, 'No todo in editing mode');
  const editInput = editingLi.querySelector('.edit');
  assert.ok(editInput, 'Edit input not found');
  assert.strictEqual(this.document.activeElement, editInput, 'Edit input should be focused');
});

Then('no todo has the CSS class {string}', function (className) {
  const todos = this.findAllTodos();
  for (const todo of todos) {
    assert.ok(!todo.classList.contains(className), `No todo should have class "${className}"`);
  }
});

Then('the counter shows {string}', function (text) {
  const countEl = this.document.querySelector('.todo-count');
  assert.ok(countEl, '.todo-count not found');
  assert.strictEqual(countEl.textContent.trim(), text, `Counter should show "${text}"`);
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  assert.ok(toggleAll, 'Toggle-all checkbox not found');
  assert.strictEqual(toggleAll.checked, true, 'Toggle-all should be checked');
});

Then('the toggle-all checkbox is unchecked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  assert.ok(toggleAll, 'Toggle-all checkbox not found');
  assert.strictEqual(toggleAll.checked, false, 'Toggle-all should be unchecked');
});

Then('the {string} button is not visible', function (buttonText) {
  const buttons = this.document.querySelectorAll('button');
  let found = false;
  for (const btn of buttons) {
    if (btn.textContent.trim() === buttonText) {
      found = true;
      const style = this.window.getComputedStyle(btn);
      assert.strictEqual(style.display, 'none', `Button "${buttonText}" should be hidden`);
      break;
    }
  }
  assert.ok(found, `Button "${buttonText}" not found`);
});

Then('the {string} button is visible', function (buttonText) {
  const buttons = this.document.querySelectorAll('button');
  let found = false;
  for (const btn of buttons) {
    if (btn.textContent.trim() === buttonText) {
      found = true;
      const style = this.window.getComputedStyle(btn);
      assert.notStrictEqual(style.display, 'none', `Button "${buttonText}" should be visible`);
      break;
    }
  }
  assert.ok(found, `Button "${buttonText}" not found`);
});

Then('the {string} filter link has the CSS class {string}', function (filter, className) {
  const routes = { All: '#/', Active: '#/active', Completed: '#/completed' };
  const href = routes[filter];
  const links = this.document.querySelectorAll('.filters a');
  let found = false;
  for (const link of links) {
    if (link.getAttribute('href') === href) {
      found = true;
      assert.ok(link.classList.contains(className), `Filter link "${filter}" should have class "${className}"`);
      break;
    }
  }
  assert.ok(found, `Filter link "${filter}" not found`);
});

