/**
 * TodoMVC Application
 * Vanilla JavaScript implementation with localStorage persistence and routing.
 */

(function () {
  'use strict';

  var STORAGE_KEY = 'todos-shakedown';

  // ==================== Model ====================

  var todos = [];

  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
  }

  function loadTodos() {
    try {
      var data = localStorage.getItem(STORAGE_KEY);
      todos = data ? JSON.parse(data) : [];
    } catch (e) {
      todos = [];
    }
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function addTodo(title) {
    var trimmed = title.trim();
    if (!trimmed) return null;
    var todo = { id: generateId(), title: trimmed, completed: false };
    todos.push(todo);
    saveTodos();
    return todo;
  }

  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        saveTodos();
        return todos[i];
      }
    }
    return null;
  }

  function toggleAll() {
    var allCompleted = todos.every(function (t) { return t.completed; });
    todos.forEach(function (t) { t.completed = !allCompleted; });
    saveTodos();
  }

  function updateTodoTitle(id, newTitle) {
    var trimmed = newTitle.trim();
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        if (!trimmed) {
          todos.splice(i, 1);
        } else {
          todos[i].title = trimmed;
        }
        saveTodos();
        return true;
      }
    }
    return false;
  }

  function destroyTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos.splice(i, 1);
        saveTodos();
        return true;
      }
    }
    return false;
  }

  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos();
  }

  function getActiveCount() {
    return todos.filter(function (t) { return !t.completed; }).length;
  }

  // ==================== Routing ====================

  function getFilter() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function getFilteredTodos() {
    var filter = getFilter();
    if (filter === 'active') return todos.filter(function (t) { return !t.completed; });
    if (filter === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos.slice();
  }

  // ==================== View ====================

  function render() {
    var todoList = document.querySelector('.todo-list');
    var main = document.querySelector('.main');
    var footer = document.querySelector('.footer');
    var toggleAll = document.querySelector('#toggle-all');
    var newTodoInput = document.querySelector('.new-todo');
    var countEl = document.querySelector('.todo-count');
    var clearBtn = document.querySelector('.clear-completed');

    if (!todoList) return;

    var filtered = getFilteredTodos();
    var allCompleted = todos.length > 0 && todos.every(function (t) { return t.completed; });

    // Render todo items
    todoList.innerHTML = '';
    filtered.forEach(function (todo) {
      var li = document.createElement('li');
      li.setAttribute('data-id', todo.id);
      if (todo.completed) li.classList.add('completed');

      var viewDiv = document.createElement('div');
      viewDiv.className = 'view';

      var checkbox = document.createElement('input');
      checkbox.className = 'toggle';
      checkbox.type = 'checkbox';
      checkbox.checked = todo.completed;

      var label = document.createElement('label');
      label.textContent = todo.title;

      var destroyBtn = document.createElement('button');
      destroyBtn.className = 'destroy';

      viewDiv.appendChild(checkbox);
      viewDiv.appendChild(label);
      viewDiv.appendChild(destroyBtn);

      var editInput = document.createElement('input');
      editInput.className = 'edit';
      editInput.value = todo.title;

      li.appendChild(viewDiv);
      li.appendChild(editInput);
      todoList.appendChild(li);
    });

    // Show/hide main and footer
    if (todos.length === 0) {
      main.style.display = 'none';
      footer.style.display = 'none';
    } else {
      main.style.display = '';
      footer.style.display = '';
    }

    // Toggle-all state
    if (toggleAll) {
      toggleAll.checked = todos.length > 0 && allCompleted;
    }

    // Counter
    if (countEl) {
      var activeCount = getActiveCount();
      var itemText = activeCount === 1 ? 'item' : 'items';
      countEl.innerHTML = '<strong>' + activeCount + '</strong> ' + itemText + ' left';
    }

    // Clear completed visibility
    if (clearBtn) {
      var hasCompleted = todos.some(function (t) { return t.completed; });
      clearBtn.style.display = hasCompleted ? '' : 'none';
    }

    // Filter links
    var filter = getFilter();
    var filterLinks = document.querySelectorAll('.filters a');
    filterLinks.forEach(function (link) {
      link.classList.remove('selected');
      var href = link.getAttribute('href');
      if ((filter === 'all' && href === '#/') ||
          (filter === 'active' && href === '#/active') ||
          (filter === 'completed' && href === '#/completed')) {
        link.classList.add('selected');
      }
    });
  }

  // ==================== Event Handlers ====================

  function setupEventListeners() {
    var newTodoInput = document.querySelector('.new-todo');
    var todoList = document.querySelector('.todo-list');
    var toggleAll = document.querySelector('#toggle-all');
    var clearBtn = document.querySelector('.clear-completed');

    // New todo input
    if (newTodoInput) {
      newTodoInput.addEventListener('keydown', function (e) {
        if (e.key === 'Enter' || e.keyCode === 13) {
          var title = newTodoInput.value.trim();
          if (title) {
            addTodo(title);
            newTodoInput.value = '';
            render();
          }
        }
      });
    }

    // Todo list interactions (event delegation)
    if (todoList) {
      todoList.addEventListener('click', function (e) {
        var target = e.target;
        var li = target.closest('li');
        if (!li) return;
        var id = li.getAttribute('data-id');

        if (target.classList.contains('toggle')) {
          toggleTodo(id);
          render();
        } else if (target.classList.contains('destroy')) {
          destroyTodo(id);
          render();
        }
      });

      todoList.addEventListener('dblclick', function (e) {
        var target = e.target;
        if (target.tagName !== 'LABEL') return;
        var li = target.closest('li');
        if (!li) return;

        li.classList.add('editing');
        var editInput = li.querySelector('.edit');
        if (editInput) {
          editInput.focus();
        }
      });

      todoList.addEventListener('keydown', function (e) {
        var target = e.target;
        if (!target.classList.contains('edit')) return;
        var li = target.closest('li');
        if (!li) return;
        var id = li.getAttribute('data-id');

        if (e.key === 'Enter' || e.keyCode === 13) {
          var newTitle = target.value.trim();
          if (!newTitle) {
            destroyTodo(id);
          } else {
            updateTodoTitle(id, newTitle);
          }
          render();
        } else if (e.key === 'Escape' || e.keyCode === 27) {
          li.classList.remove('editing');
          render();
        }
      });

      todoList.addEventListener('blur', function (e) {
        var target = e.target;
        if (!target.classList.contains('edit')) return;
        var li = target.closest('li');
        if (!li) return;
        var id = li.getAttribute('data-id');

        if (li.classList.contains('editing')) {
          var newTitle = target.value.trim();
          if (!newTitle) {
            destroyTodo(id);
          } else {
            updateTodoTitle(id, newTitle);
          }
          render();
        }
      }, true);
    }

    // Toggle all
    if (toggleAll) {
      toggleAll.addEventListener('click', function () {
        toggleAll();
        render();
      });
    }

    // Clear completed
    if (clearBtn) {
      clearBtn.addEventListener('click', function () {
        clearCompleted();
        render();
      });
    }

    // Hash change for routing
    window.addEventListener('hashchange', function () {
      render();
    });
  }

  // ==================== Init ====================

  function init() {
    loadTodos();
    setupEventListeners();
    render();
  }

  // Run on DOM ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

  // Expose for reload scenarios
  window.TodoApp = { init: init, render: render };
})();

.main { display: block; }
.footer { display: block; }
.clear-completed { display: block; }
.todo-list li { display: block; }
.todo-list li.editing .view { display: none; }
.todo-list li.editing .edit { display: block; }
.todo-list li .edit { display: none; }

const { World, Before, After, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

const templateHtml = fs.readFileSync(
  path.resolve(__dirname, '../../assets/app-template.index.html'),
  'utf-8'
);

const appJs = fs.readFileSync(
  path.resolve(__dirname, '../../js/app.js'),
  'utf-8'
);

const appCss = fs.readFileSync(
  path.resolve(__dirname, '../../css/app.css'),
  'utf-8'
);

class AppWorld extends World {
  constructor(params) {
    super(params);
    this.window = null;
    this.document = null;
  }

  openApp() {
    this.window = new Window({
      url: 'http://localhost/',
      pretendToBeVisual: true,
    });
    this.document = this.window.document;

    // Extract body content from template
    const bodyMatch = templateHtml.match(/<body[^>]*>([\s\S]*)<\/body>/i);
    let bodyHtml = bodyMatch ? bodyMatch[1] : '';

    // Remove sample todo items from template
    bodyHtml = bodyHtml.replace(/<li class="completed">[\s\S]*?<\/li>/g, '');
    bodyHtml = bodyHtml.replace(/<li>[\s\S]*?<\/li>/g, '');

    this.document.documentElement.innerHTML = '<head></head><body>' + bodyHtml + '</body>';

    // Inject CSS
    const styleEl = this.document.createElement('style');
    styleEl.textContent = appCss;
    this.document.head.appendChild(styleEl);

    // Execute app.js
    const scriptEl = this.document.createElement('script');
    scriptEl.textContent = appJs;
    this.document.body.appendChild(scriptEl);
  }

  typeIntoInput(input, text) {
    input.value = text;
    input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  }

  pressEnter(input) {
    const event = new this.window.KeyboardEvent('keydown', {
      key: 'Enter',
      code: 'Enter',
      keyCode: 13,
      which: 13,
      bubbles: true,
    });
    input.dispatchEvent(event);
  }

  pressEscape(input) {
    const event = new this.window.KeyboardEvent('keydown', {
      key: 'Escape',
      code: 'Escape',
      keyCode: 27,
      which: 27,
      bubbles: true,
    });
    input.dispatchEvent(event);
  }

  triggerBlur(input) {
    input.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
  }

  clickElement(el) {
    el.dispatchEvent(new this.window.Event('click', { bubbles: true }));
  }

  doubleClickElement(el) {
    el.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
  }

  hoverElement(el) {
    el.dispatchEvent(new this.window.MouseEvent('mouseenter', { bubbles: true }));
  }

  findTodoByTitle(title) {
    const labels = this.document.querySelectorAll('.todo-list li .view label');
    for (const label of labels) {
      if (label.textContent === title) {
        return label.closest('li');
      }
    }
    return null;
  }

  findAllTodos() {
    return Array.from(this.document.querySelectorAll('.todo-list li'));
  }

  getEditInput(todoEl) {
    return todoEl ? todoEl.querySelector('.edit') : null;
  }

  navigateTo(filter) {
    const routes = { All: '#/', Active: '#/active', Completed: '#/completed' };
    this.window.location.hash = routes[filter] || '#/';
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  reloadApp() {
    const todos = this.window.localStorage.getItem('todos-shakedown');
    const hash = this.window.location.hash;
    this.window.close();
    this.openApp();
    this.window.location.hash = hash;
    if (todos) {
      this.window.localStorage.setItem('todos-shakedown', todos);
    }
    this.window.dispatchEvent(new this.window.Event('load'));
    // Re-run app init
    if (this.window.TodoApp) {
      this.window.TodoApp.init();
    }
  }

  completeTodo(title) {
    const todo = this.findTodoByTitle(title);
    if (todo) {
      const checkbox = todo.querySelector('.toggle');
      if (checkbox && !checkbox.checked) {
        this.clickElement(checkbox);
      }
    }
  }
}

setWorldConstructor(AppWorld);

Before(function () {
  this.openApp();
});

After(function () {
  if (this.window) {
    this.window.close();
  }
});

